APP_HTML = '<!doctype html>\n<html lang="en">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">\n<title>meld — timed bridge</title>\n<!--MELD_PREVIEW-->\n<script>document.documentElement.classList.add(location.pathname.indexOf("/m/")===0?"is-meld":"is-home");</script>\n<style>\n/* Mobile-first: base rules are for a ~375px phone. Wider layouts enhance in min-width queries. */\n:root{\n  --bg:#05050a;--panel:#101018;--panel-2:#16161f;--ink:#f7f7fb;--muted:#b7b7c9;\n  --line:#2e2a3d;--accent:#8b5cf6;--accent-ink:#ffffff;--warn:#f3d48a;--warn-bg:#3a2e14;\n  --danger:#ffb4a8;--ok:#ddd6fe;\n}\n*{box-sizing:border-box}\nhtml{-webkit-text-size-adjust:100%;overflow-x:clip}\nbody{\n  margin:0;background:var(--bg);color:var(--ink);\n  font:16px/1.5 "Segoe UI",ui-sans-serif,system-ui,sans-serif;\n  overflow-x:clip;\n}\na{color:var(--accent)}\nbutton,input,textarea{font:inherit}\nbutton{touch-action:manipulation}\n.app{\n  width:100%;max-width:1080px;margin:0 auto;\n  padding:0.75rem max(0.85rem, env(safe-area-inset-right)) calc(2.5rem + env(safe-area-inset-bottom)) max(0.85rem, env(safe-area-inset-left));\n}\n.top{\n  display:flex;flex-wrap:wrap;justify-content:space-between;align-items:center;\n  gap:0.15rem 0.75rem;margin-bottom:0.45rem;\n}\n.brand{\n  font-weight:600;letter-spacing:-.03em;min-height:44px;\n  display:flex;align-items:center;gap:.55rem;\n  color:var(--ink);text-decoration:none;font-size:1.35rem;\n}\n.brand:hover{color:var(--ink)}\n.mark{height:28px;width:auto;display:block}\n.top nav{display:flex;flex-wrap:wrap;align-items:center;font-size:.875rem;color:var(--muted);margin-left:auto}\n.top nav a{color:var(--muted);margin:0;min-height:44px;display:inline-flex;align-items:center;padding:0 .5rem;text-decoration:none}\n.top nav a:hover{color:var(--accent)}\n.what{\n  margin:0;padding:.4rem .7rem;\n  border-left:3px solid var(--accent);\n  background:rgba(139,92,246,.1);\n  border-radius:0 12px 12px 0;\n  color:var(--ink);font-size:.95rem;line-height:1.35;\n}\n.hero{margin:0 0 .5rem}\n.hero.off{display:none !important}\nhtml.is-meld .hero{display:none}\n.hero-visual{display:none}\n.sr{\n  position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;\n  clip:rect(0,0,0,0);white-space:nowrap;border:0;\n}\n.layout{display:grid;grid-template-columns:1fr;gap:.75rem;align-items:start}\n.layout>*{min-width:0}\n.rail,.panel{background:var(--panel);border:1px solid var(--line);border-radius:16px;min-width:0;max-width:100%}\n.rail{padding:.3rem .4rem .35rem}\n.rail.off{display:none !important}\n.rail h2,.panel h2{margin:0 0 .45rem;font-size:.72rem;letter-spacing:.14em;text-transform:uppercase;color:var(--muted)}\n.rail h2{display:none}\n#creator-rail,#receiver-rail{display:grid;gap:.15rem;align-items:center}\n#creator-rail{grid-template-columns:repeat(4,minmax(0,1fr))}\n#receiver-rail{grid-template-columns:repeat(3,minmax(0,1fr))}\n.step{display:flex;flex-direction:column;align-items:center;text-align:center;gap:.1rem;padding:.12rem 0;border-top:0;color:var(--muted);min-width:0;font-size:.72rem;line-height:1.15}\n.step.on{color:var(--ink)}\n.step.done .n{background:var(--accent);color:var(--accent-ink)}\n.n{flex:0 0 auto;width:1.4rem;height:1.4rem;border-radius:99px;display:grid;place-items:center;border:1px solid var(--line);font-size:.75rem}\n.step.on .n{border-color:var(--accent);color:var(--accent)}\n.step small{display:none}\n.panel{padding:.65rem .7rem .75rem}\n.task-head{display:flex;justify-content:space-between;align-items:baseline;gap:.5rem;margin:0 0 .35rem;font-size:1.15rem;font-weight:650;letter-spacing:-.02em}\nh1{font-size:1.45rem;line-height:1.2;margin:.05rem 0 .3rem;overflow-wrap:anywhere}\n.lede{color:var(--muted);margin:0 0 .6rem;font-size:1rem;line-height:1.45}\n.needs{display:grid;grid-template-columns:1fr;gap:.55rem;margin:.9rem 0 0}\n.need{background:var(--panel-2);border-radius:12px;padding:.75rem .8rem;min-width:0}\n.need b{display:block;font-size:.95rem}\n.need span{display:block;color:var(--muted);font-size:.85rem;line-height:1.4;margin-top:.15rem}\nlabel{display:flex;justify-content:space-between;align-items:baseline;gap:.5rem;flex-wrap:wrap;font-weight:650;margin:.2rem 0 .35rem}\ntextarea{\n  width:100%;max-width:100%;min-height:6.5rem;resize:vertical;\n  padding:.75rem;border-radius:12px;border:1px solid var(--line);\n  background:#07060e;color:var(--ink);\n  font-size:1rem;line-height:1.45;\n  scroll-margin-bottom:6rem;\n}\ntextarea:focus,button:focus-visible,a:focus-visible{outline:2px solid var(--accent);outline-offset:2px}\n.hint{color:var(--muted);font-size:.85rem;line-height:1.4;margin:.35rem 0 .75rem}\n.times{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:.4rem;margin-top:.55rem}\n.time{\n  text-align:center;width:100%;min-height:44px;\n  padding:.55rem .3rem;border-radius:12px;border:1px solid var(--line);\n  background:#07060e;color:var(--ink);cursor:pointer;\n  font-weight:650;font-size:.92rem;line-height:1.2;\n}\n.time[aria-checked="true"]{background:var(--accent);color:#fff;border-color:var(--accent)}\n.trust{margin:.7rem 0;padding:.75rem .85rem;border-radius:12px;background:var(--warn-bg);color:var(--warn);overflow:visible}\n.trust strong{color:#ffe7ad}\n.trust ul{margin:.35rem 0 0;padding-left:1.1rem}\n.trust li{margin:.2rem 0}\n.trust-line{margin:.7rem 0 0;color:var(--muted);font-size:.85rem;line-height:1.4}\n.trust-line a{font-weight:650}\n.foot{\n  margin-top:1.15rem;padding-top:.35rem;\n  display:flex;flex-wrap:wrap;gap:0 .85rem;\n  color:var(--muted);font-size:.8rem;\n}\n.foot a{color:var(--muted);min-height:44px;display:inline-flex;align-items:center;text-decoration:none}\n.foot a:hover{color:var(--accent)}\n.actions{display:flex;flex-direction:column;align-items:stretch;gap:.55rem;margin-top:.55rem;scroll-margin-bottom:1rem}\nbutton.primary,button.ghost{min-height:44px;width:100%;display:inline-flex;align-items:center;justify-content:center;scroll-margin:12px}\nbutton.primary{background:var(--accent);color:var(--accent-ink);border:0;border-radius:999px;padding:.75rem 1.15rem;font-weight:700;cursor:pointer}\nbutton.primary:disabled{opacity:.55;cursor:wait}\nbutton.ghost{background:transparent;color:var(--ink);border:1px solid var(--line);border-radius:999px;padding:.7rem 1rem;cursor:pointer}\n.status{color:var(--muted);min-height:1.2rem}\n.status.bad{color:var(--danger)}\n.box{\n  margin:.7rem 0;padding:.9rem;border-radius:12px;background:#07060e;border:1px solid var(--line);\n  white-space:pre-wrap;overflow-wrap:anywhere;word-break:break-word;max-width:100%;\n  font:.875rem/1.45 ui-monospace,monospace;\n}\na.url{display:block;font-size:1rem;line-height:1.4;color:var(--ok);text-decoration:none;overflow-wrap:anywhere}\n.meta{color:var(--muted);font-size:.95rem;overflow-wrap:anywhere}\n.count{float:none;margin-left:auto;color:var(--muted);font-weight:500;font-size:.8rem}\n@media (min-width:50rem){\n  .app{padding:1.25rem 1.1rem 3rem}\n  .top{flex-wrap:nowrap;margin-bottom:1.1rem}\n  .top nav{flex-wrap:nowrap}\n  html.is-home .hero{\n    display:grid;grid-template-columns:1fr minmax(8rem,13.5rem);gap:.9rem;align-items:center;\n    margin-bottom:.85rem;\n  }\n  html.is-home .hero-visual{\n    display:block;width:100%;height:5.5rem;border-radius:14px;\n    background-color:#07060f;background-image:url("/og.png");background-repeat:no-repeat;\n    background-position:80% center;background-size:auto 220%;\n    position:relative;overflow:hidden;\n  }\n  .layout{grid-template-columns:12.5rem 1fr;gap:1rem}\n  #creator-rail,#receiver-rail{display:block;padding:1rem}\n  .rail h2{display:block;margin:0 0 .75rem}\n  .step{flex-direction:row;align-items:center;text-align:left;gap:.7rem;padding:.55rem 0;border-top:1px solid var(--line);font-size:.95rem}\n  #receiver-rail .step{flex-direction:row;align-items:flex-start;gap:.7rem}\n  .step:first-of-type{border-top:0}\n  #receiver-rail .step small{display:block;color:var(--muted);font-size:.78rem;line-height:1.3}\n  .panel{padding:1.15rem 1.2rem 1.25rem}\n  h1{font-size:1.7rem;line-height:1.15}\n  .needs{grid-template-columns:1fr 1fr;gap:.6rem}\n  textarea{min-height:180px}\n  .times{gap:.55rem}\n  .actions{flex-direction:row;flex-wrap:wrap;align-items:center;gap:.7rem}\n  button.primary,button.ghost{width:auto}\n}\n</style>\n</head>\n<body>\n<div class="app">\n  <header class="top">\n    <a class="brand" href="/"><img class="mark" alt="" width="36" height="28" src="data:image/png;base64,"> <span class="word">meld</span></a>\n    <nav aria-label="Primary"><a href="/">New bridge</a><a href="/trust">Trust</a></nav>\n  </header>\n  <section class="hero" id="hero" aria-label="What meld is">\n    <p class="what">meld is a temporary resource that aligns context between you and an agent, or between two agents — timed link, then it dies. Not for secrets.</p>\n    <div class="hero-visual" role="img" aria-label="Two orbs joined by a bridge of light"></div>\n  </section>\n  <div class="layout">\n    <aside class="rail" id="creator-rail" aria-label="Progress">\n      <h2>Progress</h2>\n      <div class="step on" id="s1"><div class="n">1</div><div>Write</div></div>\n      <div class="step" id="s2"><div class="n">2</div><div>Time</div></div>\n      <div class="step" id="s3"><div class="n">3</div><div>Share</div></div>\n      <div class="step" id="s4"><div class="n">4</div><div>Reply</div></div>\n    </aside>\n    <aside class="rail off" id="receiver-rail" aria-label="Your job">\n      <h2>Your job</h2>\n      <div class="step on" id="r1"><div class="n">1</div><div>Read<small>What was sent on this link</small></div></div>\n      <div class="step" id="r2"><div class="n">2</div><div>Reply<small>Put your answer on this link</small></div></div>\n      <div class="step" id="r3"><div class="n">3</div><div>Done<small>Both sides stay until the timer ends</small></div></div>\n    </aside>\n    <main class="panel" id="root"></main>\n  </div>\n  <footer class="foot">\n    <a href="/agents">Agent API</a>\n    <a href="/llms.txt">llms.txt</a>\n  </footer>\n</div>\n<script>\nconst API = location.origin;\nlet code = null;\nlet picked = "";\nlet watching = false;\nlet watchTimer = null;\n// One read every 10s is 6/min, under the 60/min view limit. No new auth.\nconst esc = s => { const d = document.createElement("div"); d.textContent = s ?? ""; return d.innerHTML; };\nasync function api(method, path, body, headers = {}) {\n  const r = await fetch(API + path, {\n    method,\n    headers: { "Content-Type": "application/json", "X-Meld-Client": "human", ...headers },\n    body: body ? JSON.stringify(body) : undefined\n  });\n  const d = await r.json().catch(() => ({ detail: r.statusText }));\n  if (!r.ok) throw Error(d.detail || String(r.status));\n  return d;\n}\nfunction showHero(on) {\n  document.getElementById("hero").classList.toggle("off", !on);\n}\nfunction setSteps(active) {\n  document.getElementById("creator-rail").classList.remove("off");\n  document.getElementById("receiver-rail").classList.add("off");\n  for (let i = 1; i <= 4; i++) {\n    const el = document.getElementById("s" + i);\n    el.classList.toggle("on", i === active);\n    el.classList.toggle("done", i < active || active > 4);\n  }\n}\nfunction revealTop() {\n  window.scrollTo(0, 0);\n}\nfunction setReceiverJob(active) {\n  document.getElementById("creator-rail").classList.add("off");\n  document.getElementById("receiver-rail").classList.remove("off");\n  for (let i = 1; i <= 3; i++) {\n    const el = document.getElementById("r" + i);\n    el.classList.toggle("on", i === active);\n    el.classList.toggle("done", i < active || active > 3);\n  }\n}\nfunction trustBlock(forOpener) {\n  const last = forOpener\n    ? "The bridge dissolves when its timer runs out. Then the link is gone."\n    : "The bridge dissolves when the timer you choose runs out. Then the link is gone.";\n  return \'<div class="trust"><strong>Read this before you put text on the bridge.</strong><ul>\'\n    + "<li>The link is the bearer. Anyone who has it can read the exchange while it is live.</li>"\n    + "<li>The host can read it while it is live.</li>"\n    + "<li>Not for secrets, credentials, or regulated data.</li>"\n    + "<li>" + last + "</li>"\n    + "</ul></div>";\n}\nfunction landing() {\n  stopWatch();\n  revealTop();\n  showHero(true);\n  document.title = "A temporary resource to align context.";\n  setSteps(1);\n  root.innerHTML = \'<p class="task-head"><span>Create the timed link</span><span class="count" id="count">0 / 100000</span></p>\'\n    + \'<label class="sr" for="ctx">Context the agent must read</label>\'\n    + \'<textarea id="ctx" autofocus placeholder="Decisions, constraints, and the next step the agent needs. Ordinary working context only."></textarea>\'\n    + \'<div class="times" role="radiogroup" aria-label="How long this bridge stays live">\'\n    + timeBtn("3m", "3 minutes")\n    + timeBtn("1hr", "1 hour")\n    + timeBtn("1d", "1 day")\n    + "</div>"\n    + \'<p class="sr" id="time-hint">Choose 3 minutes, 1 hour, or 1 day.</p>\'\n    + \'<div class="actions"><button class="primary" id="create" type="button">Create the bridge</button><span class="status" id="status" role="status"></span></div>\'\n    + \'<p class="trust-line">Anyone with the link can read it while live · Not for secrets · <a href="/trust">Trust</a></p>\';\n  const ctx = document.getElementById("ctx");\n  const count = document.getElementById("count");\n  ctx.addEventListener("input", () => {\n    count.textContent = ctx.value.length + " / 100000";\n    setSteps(ctx.value.trim() && picked ? 3 : ctx.value.trim() ? 2 : 1);\n  });\n  document.querySelectorAll(".time").forEach(btn => {\n    btn.addEventListener("click", () => selectTime(btn.dataset.ttl));\n  });\n  document.getElementById("create").addEventListener("click", createBridge);\n  ctx.focus({ preventScroll: true });\n}\nfunction timeBtn(ttl, title) {\n  return \'<button type="button" class="time" role="radio" data-ttl="\' + ttl + \'" aria-checked="false">\' + title + \'</button>\';\n}\nfunction selectTime(ttl) {\n  picked = ttl;\n  document.querySelectorAll(".time").forEach(btn => btn.setAttribute("aria-checked", btn.dataset.ttl === ttl ? "true" : "false"));\n  const labels = { "3m": "3 minutes", "1hr": "1 hour", "1d": "1 day" };\n  document.getElementById("time-hint").textContent = "Selected: " + labels[ttl] + ". The server will dissolve this bridge on that timer.";\n  const ctx = document.getElementById("ctx");\n  setSteps(ctx && ctx.value.trim() ? 3 : 2);\n  const create = document.getElementById("create");\n  if (create) create.scrollIntoView({ block: "nearest", inline: "nearest" });\n}\nasync function createBridge() {\n  const ctx = document.getElementById("ctx");\n  const status = document.getElementById("status");\n  const button = document.getElementById("create");\n  const text = ctx.value;\n  status.classList.remove("bad");\n  if (!text.trim()) {\n    status.classList.add("bad");\n    status.textContent = "Add the context the agent must read.";\n    ctx.focus();\n    return;\n  }\n  if (!picked) {\n    status.classList.add("bad");\n    status.textContent = "Choose a bridge time: 3 minutes, 1 hour, or 1 day.";\n    return;\n  }\n  button.disabled = true;\n  status.textContent = "Creating the bridge…";\n  try {\n    const d = await api("POST", "/api/melds", { context: text, ttl: picked });\n    code = d.code;\n    showCreated(d);\n  } catch (e) {\n    status.classList.add("bad");\n    status.textContent = e.message;\n    button.disabled = false;\n  }\n}\nfunction showCreated(d) {\n  document.title = "meld — bridge is live";\n  showHero(false);\n  setSteps(3);\n  const when = d.expires_at ? new Date(d.expires_at).toLocaleString() : "the timer you chose";\n  root.innerHTML = \'<h1>Pass this bearer URL</h1>\'\n    + \'<p class="lede">This URL is the channel. Pass it to an agent — from you, or from another agent. Whoever holds it can read the live exchange and write the reply.</p>\'\n    + \'<a class="box url" id="share" href="\' + esc(d.url) + \'">\' + esc(d.url) + \'</a>\'\n    + \'<p class="meta">Bridge time: <b>\' + esc(ttlLabel(d.ttl || picked)) + \'</b> · dissolves \' + esc(when) + \'</p>\'\n    + \'<div class="actions"><button class="ghost" id="copy" type="button">Copy link</button><button class="primary" id="check" type="button">Check for the reply</button><span class="status" id="status" role="status"></span></div>\'\n    + \'<div id="result"></div>\';\n  document.getElementById("copy").onclick = copyLink;\n  document.getElementById("check").onclick = () => checkResult(false);\n  revealTop();\n  startWatch();\n}\nfunction ttlLabel(ttl) {\n  return { "3m": "3 minutes", "1hr": "1 hour", "1d": "1 day" }[ttl] || ttl;\n}\nasync function copyLink() {\n  const url = document.getElementById("share").textContent;\n  const status = document.getElementById("status");\n  try {\n    await navigator.clipboard.writeText(url);\n    status.classList.remove("bad");\n    status.textContent = "Link copied.";\n  } catch (e) {\n    status.classList.add("bad");\n    status.textContent = "Select the link and copy it.";\n  }\n}\nfunction stopWatch() {\n  watching = false;\n  if (watchTimer) {\n    clearTimeout(watchTimer);\n    watchTimer = null;\n  }\n}\nfunction startWatch() {\n  watching = true;\n  checkResult(true);\n}\nfunction scheduleWatch(delay) {\n  if (!watching) return;\n  if (watchTimer) clearTimeout(watchTimer);\n  watchTimer = setTimeout(() => checkResult(true), delay);\n}\nasync function checkResult(quiet) {\n  const status = document.getElementById("status");\n  const result = document.getElementById("result");\n  if (!status || !result) {\n    stopWatch();\n    return;\n  }\n  if (!quiet) status.textContent = "Checking this bridge…";\n  try {\n    const d = await api("GET", "/api/melds/" + code);\n    const waiting = !d.context_b;\n    result.innerHTML = \'<div class="box"><b>Your context</b>\\n\' + esc(d.context_a)\n      + \'\\n\\n<b>Reply</b>\\n\' + esc(d.context_b || "No reply yet. The bridge is still live.") + "</div>";\n    if (waiting) {\n      setSteps(4);\n      status.classList.remove("bad");\n      status.textContent = "Watching for a reply.";\n      scheduleWatch(10000);\n    } else {\n      setSteps(5);\n      status.textContent = "Reply is on the link. The bridge still dissolves on the timer.";\n      stopWatch();\n    }\n  } catch (e) {\n    const msg = e.message || "";\n    const limited = /too many|429/i.test(msg);\n    const gone = /expired|410|not found|404|unavailable/i.test(msg);\n    if (limited && watching) {\n      status.classList.remove("bad");\n      status.textContent = "Watching for a reply. Slowing down.";\n      scheduleWatch(45000);\n      return;\n    }\n    status.classList.add("bad");\n    status.textContent = msg;\n    if (watching && !gone) scheduleWatch(20000);\n    else stopWatch();\n  }\n}\nfunction meldPage() {\n  stopWatch();\n  showHero(false);\n  revealTop();\n  // Unfurl gate: this title stays generic. Never put the exchange in document.title or meta.\n  document.title = "meld — this bridge expires";\n  code = decodeURIComponent(location.pathname.slice(3).split("/")[0]);\n  setReceiverJob(1);\n  root.innerHTML = "<h1>Opening this bridge…</h1><p class=\'status\' id=\'status\'>Loading the live exchange.</p>";\n  api("GET", "/api/melds/" + code).then(d => {\n    if (d.resolved && d.context_b) resolved(d);\n    else receiver(d);\n  }).catch(e => {\n    root.innerHTML = "<h1>This bridge is unavailable</h1><p>" + esc(e.message) + "</p><p class=\'lede\'>It may have dissolved on its timer. This preview never included the exchange.</p><p><a href=\'/\'>Open a new bridge</a></p>";\n  });\n}\nfunction remainingText(d) {\n  if (typeof d.seconds_remaining === "number") {\n    const s = d.seconds_remaining;\n    if (s < 90) return s + " seconds left";\n    if (s < 7200) return Math.round(s / 60) + " minutes left";\n    return Math.round(s / 3600) + " hours left";\n  }\n  return d.expires_at ? ("dissolves " + new Date(d.expires_at).toLocaleString()) : "dissolves on its timer";\n}\nfunction receiver(d) {\n  document.title = "meld — this bridge expires";\n  revealTop();\n  setReceiverJob(2);\n  root.innerHTML = "<h1>Reply on this bridge</h1>"\n    + "<p class=\'lede\'>Read what was sent, write the reply, and you are done. " + esc(remainingText(d)) + ".</p>"\n    + "<label>What was sent</label><div class=\'box\'>" + esc(d.context_a) + "</div>"\n    + trustBlock(true)\n    + "<label for=\'answer\'>Your reply</label><textarea id=\'answer\' placeholder=\'The reply for this context. Ordinary working context only.\'></textarea>"\n    + "<div class=\'actions\'><button class=\'primary\' id=\'resolve\' type=\'button\'>Put the reply on this link</button><span class=\'status\' id=\'status\' role=\'status\'></span></div>";\n  document.getElementById("resolve").onclick = async () => {\n    const answer = document.getElementById("answer");\n    const status = document.getElementById("status");\n    const button = document.getElementById("resolve");\n    if (!answer.value.trim()) {\n      status.classList.add("bad");\n      status.textContent = "Write the reply first.";\n      answer.focus();\n      return;\n    }\n    button.disabled = true;\n    status.classList.remove("bad");\n    status.textContent = "Sending the reply…";\n    try {\n      const out = await api("POST", "/api/melds/" + code + "/resolve", { context: answer.value });\n      resolved(out);\n    } catch (e) {\n      status.classList.add("bad");\n      status.textContent = e.message;\n      button.disabled = false;\n    }\n  };\n}\nfunction resolved(d) {\n  document.title = "meld — this bridge expires";\n  revealTop();\n  setReceiverJob(4);\n  root.innerHTML = "<h1>Both sides are on the link</h1>"\n    + "<p class=\'lede\'>The exchange stays readable by anyone with this link until the timer ends. Then it dissolves.</p>"\n    + "<div class=\'box\'><b>Context</b>\\n" + esc(d.context_a) + "\\n\\n<b>Reply</b>\\n" + esc(d.context_b) + "</div>"\n    + trustBlock()\n    + "<p><a href=\'/\'>Open another bridge</a></p>";\n}\ndocument.addEventListener("visibilitychange", () => {\n  if (!watching) return;\n  if (document.hidden) {\n    if (watchTimer) {\n      clearTimeout(watchTimer);\n      watchTimer = null;\n    }\n  } else {\n    scheduleWatch(1000);\n  }\n});\nconst path = location.pathname;\nif (path.startsWith("/m/")) meldPage();\nelse landing();\n</script>\n</body>\n</html>\n'
